questionvariables.text:
plist: [[["DA","CE","skw","DA and CE never meet, and they point in different directions, so no flat surface contains both: they are skew."],["AC","EG","par","AC and EG point in the same direction: EG is AC moved across the cuboid without turning, so they are parallel."],["AH","DE","int","AH and DE cross at the centre of the face ADHE, so they intersect."],["DH","AH","int","DH and AH meet at H."]],[["GH","DG","int","GH and DG meet at G."],["BE","DG","skw","BE and DG never meet, and they point in different directions, so no flat surface contains both: they are skew."],["BD","FH","par","BD and FH point in the same direction: FH is BD moved across the cuboid without turning, so they are parallel."],["AE","BF","par","AE and BF point in the same direction: BF is AE moved across the cuboid without turning, so they are parallel."]],[["CF","AG","skw","CF and AG never meet, and they point in different directions, so no flat surface contains both: they are skew."],["AH","BG","par","AH and BG point in the same direction: BG is AH moved across the cuboid without turning, so they are parallel."],["EG","FH","int","EG and FH cross at the centre of the top EFGH, so they intersect."],["CG","DE","skw","CG and DE never meet, and they point in different directions, so no flat surface contains both: they are skew."]],[["EF","CH","skw","EF and CH never meet, and they point in different directions, so no flat surface contains both: they are skew."],["DH","CF","skw","DH and CF never meet, and they point in different directions, so no flat surface contains both: they are skew."],["BG","BH","int","BG and BH meet at B."],["BE","CH","par","BE and CH point in the same direction: CH is BE moved across the cuboid without turning, so they are parallel."]],[["AG","DF","int","AG and DF cross at the centre of the cuboid, so they intersect."],["HE","BG","skw","HE and BG never meet, and they point in different directions, so no flat surface contains both: they are skew."],["DE","CF","par","DE and CF point in the same direction: CF is DE moved across the cuboid without turning, so they are parallel."],["CG","CH","int","CG and CH meet at C."]],[["HE","CH","int","HE and CH meet at H."],["CG","BD","skw","CG and BD never meet, and they point in different directions, so no flat surface contains both: they are skew."],["DA","FG","par","DA and FG point in the same direction: FG is DA moved across the cuboid without turning, so they are parallel."],["EF","AF","int","EF and AF meet at F."]],[["AB","AC","int","AB and AC meet at A."],["BG","CF","int","BG and CF cross at the centre of the face BCGF, so they intersect."],["BC","FG","par","BC and FG point in the same direction: FG is BC moved across the cuboid without turning, so they are parallel."],["AE","BH","skw","AE and BH never meet, and they point in different directions, so no flat surface contains both: they are skew."]],[["AC","FH","skw","AC and FH never meet, and they point in different directions, so no flat surface contains both: they are skew."],["BD","DG","int","BD and DG meet at D."],["FG","HE","par","FG and HE point in the same direction: HE is FG moved across the cuboid without turning, so they are parallel."],["DH","CH","int","DH and CH meet at H."]],[["CD","FG","skw","CD and FG never meet, and they point in different directions, so no flat surface contains both: they are skew."],["AE","CG","par","AE and CG point in the same direction: CG is AE moved across the cuboid without turning, so they are parallel."],["HE","DF","skw","HE and DF never meet, and they point in different directions, so no flat surface contains both: they are skew."],["AF","BE","int","AF and BE cross at the centre of the face ABFE, so they intersect."]],[["BF","BH","int","BF and BH meet at B."],["CD","AE","skw","CD and AE never meet, and they point in different directions, so no flat surface contains both: they are skew."],["HE","BH","int","HE and BH meet at H."],["BC","HE","par","BC and HE point in the same direction: HE is BC moved across the cuboid without turning, so they are parallel."]]];
/* Design: classify pairs of lines in a cuboid as parallel, intersecting or skew. Fixed category order in every dropdown; one wrong branch per row: the entry's reason states the true relation, which answers either wrong choice. Source: adapted from SMP Book 5 (Metric), Chapter 13, 2.5 (Fig. 8(a)). */
ix: 1+rand(10); PP: plist[ix];
c1: PP[1][3]; c2: PP[2][3]; c3: PP[3][3]; c4: PP[4][3];
opt1: [["par1",is(c1="par"),"parallel"],["int1",is(c1="int"),"intersecting"],["skw1",is(c1="skw"),"skew"]];
opt2: [["par2",is(c2="par"),"parallel"],["int2",is(c2="int"),"intersecting"],["skw2",is(c2="skw"),"skew"]];
opt3: [["par3",is(c3="par"),"parallel"],["int3",is(c3="int"),"intersecting"],["skw3",is(c3="skw"),"skew"]];
opt4: [["par4",is(c4="par"),"parallel"],["int4",is(c4="int"),"intersecting"],["skw4",is(c4="skw"),"skew"]];
ta1: first(mcq_correct(opt1)); ta2: first(mcq_correct(opt2)); ta3: first(mcq_correct(opt3)); ta4: first(mcq_correct(opt4));
nx1: if c1="par" then "int1" else if c1="int" then "skw1" else "par1";
nx2: if c2="par" then "int2" else if c2="int" then "skw2" else "par2";
nx3: if c3="par" then "int3" else if c3="int" then "skw3" else "par3";
nx4: if c4="par" then "int4" else if c4="int" then "skw4" else "par4";
ny1: if c1="par" then "skw1" else if c1="int" then "par1" else "int1";
ny2: if c2="par" then "skw2" else if c2="int" then "par2" else "int2";
ny3: if c3="par" then "skw3" else if c3="int" then "par3" else "int3";
ny4: if c4="par" then "skw4" else if c4="int" then "par4" else "int4";
